CNF="/Users/mac/Desktop/CHcode/.claude/database/my.cnf.prod"; DT=$(date -v-0d +%Y-%m-%d 2>/dev/null || date +%Y-%m-%d); mysql --defaults-file="$CNF" -N -e "
SELECT 'hourly' t, MAX(hr) max_hr, COUNT(*) cnt,
  SUM(CASE WHEN hr=7 THEN 1 ELSE 0 END) hr7_rows
FROM ads.ads_app_metrics_hourly_d WHERE dt='$DT';
SELECT 'app_daily' t, COUNT(*) cnt, MAX(update_time) mx FROM ads.ads_app_metrics_daily_d WHERE dt='$DT';
SELECT 'ch_daily' t, COUNT(*) cnt, MAX(update_time) mx FROM ads.ads_channel_metrics_daily_d WHERE dt='$DT';
SELECT 'dw_fresh' t, TIMESTAMPDIFF(SECOND, MAX(event_time), NOW()) lag_s FROM dw.dw_user_event_detail_new WHERE dt='$DT' LIMIT 1;
" 2>&1 | head -40

CNF="/Users/mac/Desktop/CHcode/.claude/database/my.cnf.prod"; DT=$(date +%Y-%m-%d); mysql --defaults-file="$CNF" -e "
-- hourly by hour today
SELECT hr, COUNT(*) rows_n FROM ads.ads_app_metrics_hourly_d WHERE dt='$DT' GROUP BY hr ORDER BY hr;
-- daily row counts + sample cols
SHOW COLUMNS FROM ads.ads_app_metrics_daily_d LIKE '%time%';
SHOW COLUMNS FROM ads.ads_channel_metrics_daily_d LIKE '%time%';
SELECT COUNT(*) app_daily_cnt FROM ads.ads_app_metrics_daily_d WHERE dt='$DT';
SELECT COUNT(*) ch_daily_cnt FROM ads.ads_channel_metrics_daily_d WHERE dt='$DT';
SELECT MAX(event_time) max_et, TIMESTAMPDIFF(SECOND, MAX(event_time), NOW()) lag_s
FROM dw.dw_user_event_detail_new WHERE dt='$DT';
" 2>&1 | head -80
